from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parent
r=json.loads((ROOT/'report.json').read_text())
e=lambda x:html.escape(str(x),quote=True)
css='''
:root{--paper:#f4efe4;--ink:#252924;--muted:#60645c;--line:#d8d2c5;--gold:#9a6219;--panel:#fffaf0;--deep:#26392f}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--paper);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Noto Sans TC","PingFang TC","Microsoft JhengHei",sans-serif;font-size:17px;line-height:1.85;overflow-wrap:anywhere}a{color:var(--gold);text-underline-offset:4px}a:focus-visible,summary:focus-visible,button:focus-visible{outline:3px solid var(--gold);outline-offset:5px}.wrap{max-width:1060px;margin:auto;padding:0 42px}.top{position:sticky;top:0;z-index:10;background:var(--paper);border-bottom:1px solid var(--line)}.top .wrap{min-height:62px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:13px;font-weight:750;letter-spacing:.16em;color:var(--ink);text-decoration:none}.top small{font-size:12px;letter-spacing:.03em;color:var(--muted)}header{padding:64px 0 44px}.eyebrow{font-size:12px;letter-spacing:.18em;font-weight:700;color:var(--gold);margin-bottom:20px}h1{font-family:"Noto Serif TC","Songti TC",serif;font-size:clamp(36px,6.5vw,66px);font-weight:750;line-height:1.2;margin:0 0 26px;letter-spacing:-.045em}.thesis{font-size:clamp(22px,3.6vw,33px);line-height:1.6;font-weight:650;max-width:780px;margin:0 0 20px}.intro{color:var(--muted);max-width:750px;margin:0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:34px 0 0}.stat{padding:22px 16px;border-right:1px solid var(--line)}.stat:first-child{padding-left:0}.stat:last-child{border:0}.stat b{display:block;font-size:27px;line-height:1.3;font-variant-numeric:tabular-nums}.stat span{font-size:13px;color:var(--muted)}.scope{display:flex;gap:10px;align-items:flex-start;background:var(--deep);color:#fff9eb;padding:19px 22px;margin:24px 0 0;font-size:14px}.scope strong{flex-shrink:0;color:#e3b56b}.toc{margin:0 0 30px;border:1px solid var(--line);background:var(--panel)}.toc summary{cursor:pointer;padding:15px 20px;font-weight:650;font-size:15px}.toc nav{display:grid;grid-template-columns:repeat(2,1fr);gap:3px 20px;padding:4px 20px 18px}.toc a{display:block;text-decoration:none;padding:9px 0;font-size:15px;color:var(--ink)}.toc a span{color:var(--gold);font-variant-numeric:tabular-nums;margin-right:14px}.section{padding:44px 0 8px;scroll-margin-top:20px}.section-head{display:flex;gap:20px;align-items:baseline;border-top:2px solid var(--ink);padding-top:23px}.num{font-family:Georgia,serif;font-size:35px;line-height:1;color:var(--gold)}h2{font-size:28px;line-height:1.4;margin:0;letter-spacing:-.035em}.lead{color:var(--muted);margin:16px 0 24px;max-width:780px}.items{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:var(--panel);border:1px solid var(--line);padding:27px 28px;min-width:0}.card:first-child:last-child{grid-column:1/-1}.tag{display:inline-block;border:1px solid #c5baa6;color:var(--gold);padding:1px 8px;font-size:12px;font-weight:700;letter-spacing:.04em;margin-bottom:13px}.tag[data-type="優先"],.tag[data-type="建議修正"]{background:var(--deep);border-color:var(--deep);color:#fff5df}h3{margin:0 0 14px;font-size:21px;line-height:1.55;letter-spacing:-.02em}.card p{margin:0;font-size:16px;line-height:1.9}.rec{margin-top:19px!important;border-left:3px solid #b4761e;padding-left:14px}.rec strong{display:block;color:var(--gold);font-size:12px;letter-spacing:.12em;margin-bottom:4px}.evidence{margin-top:20px;border-top:1px solid var(--line);padding-top:12px;font-size:13px;color:var(--muted)}.evidence summary{cursor:pointer;font-weight:600;min-height:34px}.evidence p{font-size:13px;line-height:1.8;margin-top:8px}footer{padding:60px 0 35px}.boundary{border-top:2px solid var(--ink);padding-top:25px}.boundary h2{font-size:23px}.boundary p{font-size:15px;color:var(--muted)}.sources{list-style:none;margin:25px 0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 22px}.sources li{border-top:1px solid var(--line);font-size:14px}.sources a{display:block;padding:12px 0}.footnote{font-size:12px;color:var(--muted)}.pending{padding:20px;background:var(--panel);border:1px dashed var(--line);color:var(--muted)}@media(max-width:760px){.wrap{padding-left:23px;padding-right:23px}.top .wrap{min-height:57px;gap:9px}.brand{font-size:11px;letter-spacing:.09em}.top small{font-size:11px}header{padding-top:37px;padding-bottom:26px}h1{font-size:39px;line-height:1.3;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.12em;margin-bottom:14px}.thesis{font-size:23px;line-height:1.65}.intro{font-size:16px}.stats{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:26px}.stat{padding:18px 0 18px 16px}.stat:nth-child(odd){padding-left:0}.stat:nth-child(2){border-right:0}.stat:nth-child(-n+2){border-bottom:1px solid var(--line)}.stat b{font-size:25px}.stat span{font-size:12px}.scope{display:block;padding:18px;font-size:13px}.scope strong{display:block;margin-bottom:5px}.toc nav{grid-template-columns:1fr}.section{padding-top:30px}.section-head{gap:14px;padding-top:18px}.num{font-size:30px}h2{font-size:24px}.lead{font-size:15px;margin:14px 0 20px}.items{grid-template-columns:1fr;gap:14px}.card{padding:23px 20px}h3{font-size:20px}.card p{font-size:16px}.sources{grid-template-columns:1fr}.evidence p{font-size:13px}footer{padding-top:42px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.top,.toc{display:none}.wrap{max-width:none}.card{break-inside:avoid}.items{display:block}.card{margin:14px 0}}
'''
parts=[]
for s in r['sections']:
    cards=[]
    for item in s['items']:
        rec=f'<p class="rec"><strong>建議做法</strong>{e(item["recommendation"])}</p>' if item.get('recommendation') else ''
        evidence=f'<details class="evidence"><summary>查看查證依據</summary><p>{e(item["evidence"])}</p></details>' if item.get('evidence') else ''
        cards.append(f'<article class="card"><span class="tag" data-type="{e(item["tag"])}">{e(item["tag"])}</span><h3>{e(item["title"])}</h3><p>{e(item["body"])}</p>{rec}{evidence}</article>')
    inner=''.join(cards) if cards else '<p class="pending">隔離檢查進行中，完成後再納入結論。</p>'
    parts.append(f'<section class="section" id="{e(s["id"])}"><div class="section-head"><span class="num">{e(s["number"])}</span><h2>{e(s["title"])}</h2></div><p class="lead">{e(s["lead"])}</p><div class="items">{inner}</div></section>')
nav=''.join(f'<a href="#{e(s["id"])}"><span>{e(s["number"])}</span>{e(s["title"])}</a>' for s in r['sections'])
stats=''.join(f'<div class="stat"><b>{e(x["value"])}</b><span>{e(x["label"])}</span></div>' for x in r['stats'])
sources=''.join(f'<li><a href="{e(x["url"])}" target="_blank" rel="noopener noreferrer">{e(x["title"])} ↗</a></li>' for x in r['sources'])
page=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f4efe4"><meta name="description" content="Hermes 系統維護審核：設定、Patch、Skill 與排程，依據實際檢查提出改善順序。"><title>{e(r['title'])} · {e(r['date'])}</title><style>{css}</style></head><body><div class="top"><div class="wrap"><a class="brand" href="#top">HERMI / SYSTEM REVIEW</a><small>{e(r['date'])} · {e(r['status'])}</small></div></div><main class="wrap" id="top"><header><div class="eyebrow">MAINTENANCE AUDIT / VERIFIED DISK CHANGES</div><h1>{e(r['title'])}</h1><p class="thesis">{e(r['subtitle'])}</p><p class="intro">{e(r['intro'])}</p><div class="stats">{stats}</div><div class="scope"><strong>磁碟修正 ≠ 服務已載入</strong><span>已保存經驗收的修正，未重啟 Gateway。此頁為公開刪節版，不含金鑰、帳號識別、完整設定或原始 Log。</span></div></header><details class="toc"><summary>跳到想看的章節</summary><nav>{nav}</nav></details>{''.join(parts)}<footer><div class="boundary"><h2>這份審核的界線</h2><p>{e(r['boundary'])}</p></div><ul class="sources">{sources}</ul><p class="footnote">依單次檢查時點呈現，不是即時監控。公開頁面已省略敏感細節；noindex 不是存取保護。</p></footer></main></body></html>'''
(ROOT/'index.html').write_text(page)
print(json.dumps({'sections':len(r['sections']),'findings':sum(len(x['items']) for x in r['sections']),'bytes':len(page.encode()),'status':r['status']},ensure_ascii=False))
